#!/usr/bin/env python3
"""Pure-stdlib synthetic PNG generator (no PIL) for the bounded live smoke.

Produces three NON-FACE synthetic patterns:
  * clear.png      : high-contrast structured detail (checkerboard + bright disk)
  * blurry.png     : nearly uniform low-contrast gradient
  * small_face.png : mostly uniform background + a tiny detailed patch

These are deliberately NOT faces. The objective is to drive the real Worker chain
and observe genuine service responses; detection/quality "success" is never assumed.
"""
from __future__ import annotations

import os
import struct
import sys
import zlib

W = H = 256


def _png(width: int, height: int, pixel) -> bytes:
    raw = bytearray()
    for y in range(height):
        raw.append(0)  # filter type 0 (None)
        for x in range(width):
            r, g, b = pixel(x, y)
            raw += bytes((r, g, b))

    def chunk(kind: bytes, data: bytes) -> bytes:
        body = struct.pack(">I", len(data)) + kind + data
        return body + struct.pack(">I", zlib.crc32(kind + data) & 0xFFFFFFFF)

    ihdr = struct.pack(">IIBBBBB", width, height, 8, 2, 0, 0, 0)  # 8-bit truecolor
    return (
        b"\x89PNG\r\n\x1a\n"
        + chunk(b"IHDR", ihdr)
        + chunk(b"IDAT", zlib.compress(bytes(raw), 9))
        + chunk(b"IEND", b"")
    )


def clear_px(x: int, y: int) -> tuple[int, int, int]:
    base = 250 if ((x // 12) + (y // 12)) % 2 == 0 else 5
    dx, dy = x - W // 2, y - H // 2
    if dx * dx + dy * dy < (W // 5) ** 2:  # bright disk
        return (base, min(255, base + 4), min(255, base + 8))
    return (base, base, base)


def blurry_px(x: int, y: int) -> tuple[int, int, int]:
    v = 126 + (x * 5) // W  # 126..131, low contrast, low detail
    return (v, v, v)


def small_face_px(x: int, y: int) -> tuple[int, int, int]:
    cx, cy = W // 2, H // 2
    if abs(x - cx) < 12 and abs(y - cy) < 12:  # tiny detailed patch
        v = 250 if ((x // 3) + (y // 3)) % 2 == 0 else 10
        return (v, v, v)
    return (200, 200, 200)  # uniform


def main() -> int:
    out_dir = sys.argv[1] if len(sys.argv) > 1 else "images"
    os.makedirs(out_dir, exist_ok=True)
    for name, fn in (
        ("clear.png", clear_px),
        ("blurry.png", blurry_px),
        ("small_face.png", small_face_px),
    ):
        data = _png(W, H, fn)
        with open(os.path.join(out_dir, name), "wb") as handle:
            handle.write(data)
        print(f"{name}: {len(data)} bytes")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Bounded live Worker->face-service smoke driver (stdlib + transplanted dshared only).

Runs ON dev.ai-skin. Reads the token in-machine via ``dtokenfile`` (0600 enforced);
never prints the token, image bytes, embeddings, or identifier values. All external
calls are bounded; the register gate MUST be closed (auto-enroll false) and is proven
to issue ZERO HTTP.

Output: one sanitized JSON report on stdout (no secrets/identifiers/bodies).
"""
from __future__ import annotations

import http.client
import json
import os
import sys
import time
from typing import Any, Callable, Optional
from urllib.parse import urlparse

from mvp_worker.handlers.dshared.dconfig import DConfig, ProviderConfigError
from mvp_worker.handlers.dshared.dtokenfile import read_token_file
from mvp_worker.handlers.dshared.dtransport import (
    FaceServiceHttpError,
    FaceServiceTransportError,
    StdlibHttpTransport,
)
from mvp_worker.handlers.dshared.providers import (
    InsightFaceAdapter,
    ProviderNotActivated,
    ProviderUnavailable,
    build_face_port,
)

BASE_URL = os.environ["MVP_D_FACE_SERVICE_BASE_URL"]
NAMESPACE = os.environ["MVP_D_FACE_SERVICE_NAMESPACE"]
TOKEN_FILE = os.environ["MVP_D_FACE_SERVICE_TOKEN_FILE"]
IMAGE_DIR = os.environ.get("SMOKE_IMAGE_DIR", "images")
TIMEOUT_S = 10


# ------------------------------------------------------------------ helpers
def _route_label(path: str) -> str:
    p = path.split("?", 1)[0]
    if p == "/v1/quality":
        return "/v1/quality"
    if p == "/v1/compare":
        return "/v1/compare"
    if p.endswith("/search"):
        return "/v1/namespaces/{ns}/search"
    if p.endswith("/subjects"):
        return "/v1/namespaces/{ns}/subjects"
    if "/registrations/" in p:
        return "/v1/namespaces/{ns}/registrations/{correlation_id}"
    return "<route>"


def raw_get(path: str, token: Optional[str] = None) -> dict[str, Any]:
    parsed = urlparse(BASE_URL)
    conn = http.client.HTTPConnection(parsed.hostname, parsed.port or 80, timeout=TIMEOUT_S)
    headers = {"Accept": "application/json"}
    if token:
        headers["X-Internal-Token"] = token
    started = time.monotonic()
    try:
        conn.request("GET", path, headers=headers)
        resp = conn.getresponse()
        raw = resp.read()
        status = int(resp.status)
        request_id = resp.getheader("X-Request-Id")
    finally:
        conn.close()
    elapsed = round((time.monotonic() - started) * 1000.0, 1)
    try:
        body = json.loads(raw.decode("utf-8"))
    except Exception:
        body = None
    return {"path": path, "status": status, "request_id": request_id,
            "elapsed_ms": elapsed, "body": body}


class RecordingTransport:
    """Delegates to the real transport and records sanitized per-call metadata."""

    def __init__(self, inner: StdlibHttpTransport) -> None:
        self._inner = inner
        self.records: list[dict[str, Any]] = []

    def request(self, method: str, path: str, *, json_body=None, headers_extra=None):
        label = _route_label(path)
        started = time.monotonic()
        try:
            result = self._inner.request(
                method, path, json_body=json_body, headers_extra=headers_extra
            )
        except FaceServiceHttpError as exc:
            self.records.append(_rec(label, exc.status, exc.code, exc.request_id, started))
            raise
        except FaceServiceTransportError as exc:
            self.records.append(_rec(label, None, type(exc).__name__, None, started))
            raise
        self.records.append(
            _rec(label, result.status, None, result.headers.get("x-request-id"), started)
        )
        return result


def _rec(route, status, code, request_id, started) -> dict[str, Any]:
    return {
        "route": route,
        "status": status,
        "code": code,
        "request_id": request_id,
        "elapsed_ms": round((time.monotonic() - started) * 1000.0, 1),
    }


def _describe(result: Any) -> dict[str, Any]:
    name = type(result).__name__
    if name == "QualityResult":
        return {"result": name, "status": result.status,
                "required_views": list(result.required_views)}
    if name == "SamePersonResult":
        return {"result": name, "ok": result.ok}
    if name == "SearchResult":
        return {"result": name, "classification": result.classification,
                "has_subject_ref": result.face_subject_ref is not None}
    if name == "RegisterResult":
        return {"result": name, "status": result.status}
    if name == "RegistrationQueryResult":
        return {"result": name, "status": result.status}
    return {"result": name}


def call(label: str, fn: Callable[[], Any]) -> dict[str, Any]:
    started = time.monotonic()
    try:
        result = fn()
    except ProviderNotActivated as exc:
        outcome = {"outcome": "ProviderNotActivated", "message": str(exc)[:200]}
    except ProviderConfigError as exc:
        outcome = {"outcome": "ProviderConfigError", "message": str(exc)[:200]}
    except ProviderUnavailable as exc:
        outcome = {"outcome": "ProviderUnavailable", "message": str(exc)[:200]}
    except Exception as exc:  # unexpected -> report type only
        outcome = {"outcome": type(exc).__name__, "message": str(exc)[:200]}
    else:
        outcome = _describe(result)
    outcome["op"] = label
    outcome["elapsed_ms"] = round((time.monotonic() - started) * 1000.0, 1)
    return outcome


def _load_images() -> dict[str, bytes]:
    def read(name: str) -> bytes:
        with open(os.path.join(IMAGE_DIR, name), "rb") as handle:
            return handle.read()

    return {"clear": read("clear.png"), "blurry": read("blurry.png"),
            "small_face": read("small_face.png")}


def main() -> int:
    os.environ.setdefault("MVP_D_FACE_PROVIDER", "insightface")
    cfg = DConfig.from_env()
    report: dict[str, Any] = {
        "base_url": BASE_URL,
        "namespace": NAMESPACE,
        "face_provider": cfg.face_provider,
        "auto_enroll_env_raw": os.environ.get("MVP_D_FACE_SERVICE_AUTO_ENROLL", "<unset>"),
        "auto_enroll_cfg": cfg.face_service_auto_enroll,
        "read_timeout_ms": cfg.face_service_read_timeout_ms,
        "connect_timeout_ms": cfg.face_service_connect_timeout_ms,
    }

    # Binding safety assertions (fail closed before any worker call).
    assert cfg.face_service_auto_enroll is False, "auto-enroll MUST be false"
    assert cfg.face_provider == "insightface", cfg.face_provider

    token = read_token_file(cfg.face_service_token_file)  # in-machine, 0600 enforced
    report["token_loaded"] = bool(token)

    images = _load_images()

    # (a) SERVICE-LEVEL smoke (public endpoints; raw http.client; distinct from Worker calls)
    service: dict[str, Any] = {}
    for name, path in (("live", "/live"), ("ready", "/ready"), ("health", "/v1/health")):
        out = raw_get(path)
        service[name] = {
            "status": out["status"],
            "request_id": out["request_id"],
            "elapsed_ms": out["elapsed_ms"],
        }
        if isinstance(out["body"], dict):
            body = out["body"]
            if "library_revision" in body:
                service[name]["library_revision"] = body["library_revision"]
            if "uptime_seconds" in body:
                service[name]["uptime_seconds"] = body["uptime_seconds"]
            if "model_loaded" in body:
                service[name]["model_loaded"] = body["model_loaded"]
            if "model_version" in body:
                service[name]["model_version"] = body["model_version"]
    report["service_level_smoke"] = service
    rev_pre = service["ready"].get("library_revision")
    uptime_pre = service["health"].get("uptime_seconds")

    # Smoke namespace absent pre (authed raw read; token never printed).
    ns_info_pre = raw_get(f"/v1/namespaces/{NAMESPACE}/info", token=token)
    report["smoke_namespace_pre_status"] = ns_info_pre["status"]

    # (b) WORKER CALLS via the real adapter + real stdlib transport
    real_transport = StdlibHttpTransport(
        base_url=BASE_URL,
        token=token,
        connect_timeout_ms=cfg.face_service_connect_timeout_ms,
        read_timeout_ms=cfg.face_service_read_timeout_ms,
    )
    recorder = RecordingTransport(real_transport)
    adapter = InsightFaceAdapter(cfg, recorder)

    # Prove the production factory seam constructs the real adapter (no calls made).
    built = build_face_port(cfg, environment="dev")
    report["build_face_port_is_insightface"] = isinstance(built, InsightFaceAdapter)

    worker: list[dict[str, Any]] = []
    worker.append(call("quality/clear-all",
                       lambda: adapter.quality({"front": images["clear"],
                                                "left": images["clear"],
                                                "right": images["clear"]})))
    worker.append(call("quality/mixed",
                       lambda: adapter.quality({"front": images["clear"],
                                                "left": images["blurry"],
                                                "right": images["small_face"]})))
    worker.append(call("same_person/clear-all",
                       lambda: adapter.same_person({"front": images["clear"],
                                                    "left": images["clear"],
                                                    "right": images["clear"]})))
    worker.append(call("same_person/mixed",
                       lambda: adapter.same_person({"front": images["clear"],
                                                    "left": images["blurry"],
                                                    "right": images["small_face"]})))
    worker.append(call("search_1n/empty-or-absent",
                       lambda: adapter.search_1n(NAMESPACE, {"front": images["clear"]})))

    # Gate-closed register: MUST raise ProviderNotActivated with ZERO HTTP.
    records_before = len(recorder.records)
    worker.append(call("register_person/gate-closed",
                       lambda: adapter.register_person(
                           NAMESPACE, "d-smoke-entity-0001", {"front": images["clear"]},
                           "d-smoke-corr-0001", "d-smoke-req-0001")))
    register_http_issued = len(recorder.records) - records_before

    worker.append(call("query_registration/synthetic",
                       lambda: adapter.query_registration(
                           "d-smoke-corr-0001", "d-smoke-req-0001",
                           namespace=NAMESPACE, entity_id="d-smoke-entity-0001")))

    report["worker_calls"] = worker
    report["transport_records"] = recorder.records
    report["register_http_issued"] = register_http_issued
    assert register_http_issued == 0, "register gate closed but HTTP was issued"
    assert isinstance(built, InsightFaceAdapter)

    # (c) POST checks: revision still 0, uptime continuity, smoke ns still absent.
    ready_post = raw_get("/ready")
    health_post = raw_get("/v1/health")
    ns_info_post = raw_get(f"/v1/namespaces/{NAMESPACE}/info", token=token)
    rev_post = (ready_post["body"] or {}).get("library_revision") if isinstance(ready_post["body"], dict) else None
    uptime_post = (health_post["body"] or {}).get("uptime_seconds") if isinstance(health_post["body"], dict) else None
    report["post"] = {
        "ready_status": ready_post["status"],
        "ready_request_id": ready_post["request_id"],
        "library_revision": rev_post,
        "health_status": health_post["status"],
        "uptime_seconds": uptime_post,
        "smoke_namespace_info_status": ns_info_post["status"],
    }
    report["library_revision_unchanged"] = (rev_pre == rev_post)
    report["uptime_continuity"] = (
        uptime_pre is not None and uptime_post is not None and uptime_post > uptime_pre
    )
    report["smoke_namespace_absent_post"] = ns_info_post["status"] == 404

    print("===EVIDENCE-JSON===")
    print(json.dumps(report, indent=2, sort_keys=True))
    print("===END===")
    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except Exception as exc:  # top-level: type + short message only
        print("===DRIVER-ERROR===")
        print(f"{type(exc).__name__}: {str(exc)[:200]}")
