#!/usr/bin/env python3
"""LIVE ROUND 2 (success paths) driver — same-machine dev.ai-skin, stdlib-only.

Reuses the round-1 transplant/infrastructure. Runs ON dev.ai-skin as ``bool``.
* Reads the token in-machine via ``dtokenfile`` (0600) — value never printed.
* Reads B's synthetic-face sample **in place** (never copied locally) and records only
  its sha256 digest.
* Reads the three faceless synthetic PNGs for the needs_retake live proof.
* Emits one sanitized JSON report: statuses/codes/decisions/classifications/booleans/
  request_ids/elapsed + selected safe scalars. Never token, bytes, embeddings or ids.

Round-1 failure-path evidence lives separately in evidence.md; do not merge.
"""
from __future__ import annotations

import hashlib
import http.client
import json
import os
import time
from typing import Any, Callable, Optional
from urllib.parse import urlparse

from mvp_worker.handlers.dshared.dconfig import DConfig, ProviderConfigError
from mvp_worker.handlers.dshared.dtokenfile import read_token_file
from mvp_worker.handlers.dshared.dtransport import (
    FaceServiceHttpError,
    FaceServiceTransportError,
    StdlibHttpTransport,
)
from mvp_worker.handlers.dshared.providers import (
    InsightFaceAdapter,
    ProviderNotActivated,
    ProviderUnavailable,
    build_face_port,
)

BASE_URL = os.environ["MVP_D_FACE_SERVICE_BASE_URL"]
NAMESPACE = os.environ["MVP_D_FACE_SERVICE_NAMESPACE"]
TOKEN_FILE = os.environ["MVP_D_FACE_SERVICE_TOKEN_FILE"]
B_SAMPLE = os.environ["SMOKE_B_SAMPLE"]
IMAGE_DIR = os.environ.get("SMOKE_IMAGE_DIR", "images")
TIMEOUT_S = 10


# ------------------------------------------------------------------ helpers
def _route_label(path: str) -> str:
    p = path.split("?", 1)[0]
    if p == "/v1/quality":
        return "/v1/quality"
    if p == "/v1/compare":
        return "/v1/compare"
    if p.endswith("/search"):
        return "/v1/namespaces/{ns}/search"
    if p.endswith("/subjects"):
        return "/v1/namespaces/{ns}/subjects"
    if "/registrations/" in p:
        return "/v1/namespaces/{ns}/registrations/{correlation_id}"
    return "<route>"


def _observe(route: str, body: Any) -> dict[str, Any]:
    """Selected safe scalars only (no ids/bytes/embeddings/bodies)."""
    if not isinstance(body, dict):
        return {}
    if route == "/v1/quality":
        obs: dict[str, Any] = {
            "face_count": body.get("face_count"),
            "largest_face_index": body.get("largest_face_index"),
        }
        faces = body.get("faces")
        if isinstance(faces, list) and faces and isinstance(faces[0], dict):
            quality = faces[0].get("quality")
            if isinstance(quality, dict):
                obs["min_acceptable"] = quality.get("min_acceptable")
        return obs
    if route == "/v1/compare":
        return {
            "matched": body.get("matched"),
            "reasons": body.get("reasons"),
            "face_count_a": body.get("face_count_a"),
            "face_count_b": body.get("face_count_b"),
        }
    if route.endswith("/search"):
        return {key: body.get(key) for key in
                ("decision", "ambiguous", "reasons", "subject_count", "top_k",
                 "policy_version", "library_revision")}
    if route.endswith("/subjects"):
        return {"created": body.get("created"), "replayed": body.get("replayed"),
                "library_revision": body.get("library_revision")}
    if "/registrations/" in route:
        return {"status": body.get("status")}
    return {}


def raw_get(path: str, token: Optional[str] = None) -> dict[str, Any]:
    parsed = urlparse(BASE_URL)
    conn = http.client.HTTPConnection(parsed.hostname, parsed.port or 80, timeout=TIMEOUT_S)
    headers = {"Accept": "application/json"}
    if token:
        headers["X-Internal-Token"] = token
    started = time.monotonic()
    try:
        conn.request("GET", path, headers=headers)
        resp = conn.getresponse()
        raw = resp.read()
        status = int(resp.status)
        request_id = resp.getheader("X-Request-Id")
    finally:
        conn.close()
    elapsed = round((time.monotonic() - started) * 1000.0, 1)
    try:
        body = json.loads(raw.decode("utf-8")) if raw else None
    except Exception:
        body = None
    return {"path": path, "status": status, "request_id": request_id,
            "elapsed_ms": elapsed, "body": body}


class RecordingTransport:
    def __init__(self, inner: StdlibHttpTransport) -> None:
        self._inner = inner
        self.records: list[dict[str, Any]] = []

    def request(self, method: str, path: str, *, json_body=None, headers_extra=None):
        label = _route_label(path)
        started = time.monotonic()
        try:
            result = self._inner.request(
                method, path, json_body=json_body, headers_extra=headers_extra
            )
        except FaceServiceHttpError as exc:
            self.records.append(_rec(label, exc.status, exc.code, exc.request_id,
                                     started, {}))
            raise
        except FaceServiceTransportError as exc:
            self.records.append(_rec(label, None, type(exc).__name__, None, started, {}))
            raise
        self.records.append(_rec(label, result.status, None,
                                 result.headers.get("x-request-id"), started,
                                 _observe(label, result.json)))
        return result


def _rec(route, status, code, request_id, started, observed) -> dict[str, Any]:
    record = {"route": route, "status": status, "code": code,
              "request_id": request_id,
              "elapsed_ms": round((time.monotonic() - started) * 1000.0, 1)}
    if observed:
        record["observed"] = observed
    return record


def _describe(result: Any) -> dict[str, Any]:
    name = type(result).__name__
    if name == "QualityResult":
        return {"result": name, "status": result.status,
                "required_views": list(result.required_views)}
    if name == "SamePersonResult":
        return {"result": name, "ok": result.ok}
    if name == "SearchResult":
        return {"result": name, "classification": result.classification,
                "has_subject_ref": result.face_subject_ref is not None}
    if name == "RegisterResult":
        return {"result": name, "status": result.status}
    if name == "RegistrationQueryResult":
        return {"result": name, "status": result.status}
    return {"result": name}


def call(label: str, fn: Callable[[], Any]) -> dict[str, Any]:
    started = time.monotonic()
    try:
        result = fn()
    except ProviderNotActivated as exc:
        outcome = {"outcome": "ProviderNotActivated", "message": str(exc)[:200]}
    except ProviderConfigError as exc:
        outcome = {"outcome": "ProviderConfigError", "message": str(exc)[:200]}
    except ProviderUnavailable as exc:
        outcome = {"outcome": "ProviderUnavailable", "message": str(exc)[:200]}
    except Exception as exc:
        outcome = {"outcome": type(exc).__name__, "message": str(exc)[:200]}
    else:
        outcome = _describe(result)
    outcome["op"] = label
    outcome["elapsed_ms"] = round((time.monotonic() - started) * 1000.0, 1)
    return outcome


def _read_file(path: str) -> bytes:
    with open(path, "rb") as handle:
        return handle.read()


def _service_smoke() -> dict[str, Any]:
    out: dict[str, Any] = {}
    for name, path in (("live", "/live"), ("ready", "/ready"), ("health", "/v1/health")):
        res = raw_get(path)
        entry: dict[str, Any] = {"status": res["status"], "request_id": res["request_id"],
                                 "elapsed_ms": res["elapsed_ms"]}
        if isinstance(res["body"], dict):
            for key in ("library_revision", "uptime_seconds", "model_loaded", "model_version"):
                if key in res["body"]:
                    entry[key] = res["body"][key]
        out[name] = entry
    return out


def main() -> int:
    os.environ.setdefault("MVP_D_FACE_PROVIDER", "insightface")
    cfg = DConfig.from_env()
    report: dict[str, Any] = {
        "base_url": BASE_URL,
        "namespace": NAMESPACE,
        "face_provider": cfg.face_provider,
        "auto_enroll_env_raw": os.environ.get("MVP_D_FACE_SERVICE_AUTO_ENROLL", "<unset>"),
        "auto_enroll_cfg": cfg.face_service_auto_enroll,
    }
    assert cfg.face_service_auto_enroll is False, "auto-enroll MUST be false"
    assert cfg.face_provider == "insightface"

    token = read_token_file(cfg.face_service_token_file)
    report["token_loaded"] = bool(token)

    # B sample read in place; digest only recorded.
    sample_bytes = _read_file(B_SAMPLE)
    report["b_sample_sha256"] = hashlib.sha256(sample_bytes).hexdigest()
    report["b_sample_bytes"] = len(sample_bytes)
    faceless = {name: _read_file(os.path.join(IMAGE_DIR, name + ".png"))
                for name in ("clear", "blurry", "small_face")}

    report["service_level_smoke_pre"] = _service_smoke()

    # (c) verify search does not create the namespace: check right after search too.
    ns_info_pre = raw_get(f"/v1/namespaces/{NAMESPACE}/info", token=token)
    report["smoke_namespace_pre_status"] = ns_info_pre["status"]

    real_transport = StdlibHttpTransport(
        base_url=BASE_URL, token=token,
        connect_timeout_ms=cfg.face_service_connect_timeout_ms,
        read_timeout_ms=cfg.face_service_read_timeout_ms,
    )
    recorder = RecordingTransport(real_transport)
    adapter = InsightFaceAdapter(cfg, recorder)

    built = build_face_port(cfg, environment="dev")
    report["build_face_port_is_insightface"] = isinstance(built, InsightFaceAdapter)

    worker: list[dict[str, Any]] = []
    # (a) FIRST live accepted quality path (B sample for all three views).
    worker.append(call("quality/b-sample-all-views",
                       lambda: adapter.quality({"front": sample_bytes,
                                                "left": sample_bytes,
                                                "right": sample_bytes})))
    # (b) FIRST live same-person path (identical-image front-anchored compares).
    worker.append(call("same_person/b-sample-all-views",
                       lambda: adapter.same_person({"front": sample_bytes,
                                                    "left": sample_bytes,
                                                    "right": sample_bytes})))
    # (c) FIRST live decision-vocabulary exercise (Absent namespace, quality OK).
    worker.append(call("search_1n/b-sample-absent-ns",
                       lambda: adapter.search_1n(NAMESPACE, {"front": sample_bytes})))

    # Namespace must NOT have been created by the read-only search.
    ns_info_after_search = raw_get(f"/v1/namespaces/{NAMESPACE}/info", token=token)
    report["smoke_namespace_status_after_search"] = ns_info_after_search["status"]

    # (d) NEEDS_RETAKE LIVE PROOF of the accepted e006e6b fix.
    #     d1: front acceptable (B sample), left/right faceless content-code 400 -> subset.
    worker.append(call("quality/needs_retake-mixed-subset",
                       lambda: adapter.quality({"front": sample_bytes,
                                                "left": faceless["blurry"],
                                                "right": faceless["small_face"]})))
    #     d2: all three faceless -> all views failing (canonical order).
    worker.append(call("quality/needs_retake-all-views",
                       lambda: adapter.quality({"front": faceless["clear"],
                                                "left": faceless["blurry"],
                                                "right": faceless["small_face"]})))

    # (e) gate-closed re-proof on the final SHA: zero HTTP.
    records_before = len(recorder.records)
    worker.append(call("register_person/gate-closed",
                       lambda: adapter.register_person(
                           NAMESPACE, "d-smoke-entity-0002", {"front": sample_bytes},
                           "d-smoke-corr-0002", "d-smoke-req-0002")))
    register_http_issued = len(recorder.records) - records_before
    report["register_http_issued"] = register_http_issued
    assert register_http_issued == 0, "register gate closed but HTTP was issued"

    # (f) reconciliation read-only, unchanged expectation.
    worker.append(call("query_registration/synthetic",
                       lambda: adapter.query_registration(
                           "d-smoke-corr-0002", "d-smoke-req-0002",
                           namespace=NAMESPACE, entity_id="d-smoke-entity-0002")))

    report["worker_calls"] = worker
    report["transport_records"] = recorder.records

    # (5) post checks
    report["service_level_smoke_post"] = _service_smoke()
    ns_info_post = raw_get(f"/v1/namespaces/{NAMESPACE}/info", token=token)
    rev_pre = report["service_level_smoke_pre"]["ready"].get("library_revision")
    rev_post = report["service_level_smoke_post"]["ready"].get("library_revision")
    uptime_pre = report["service_level_smoke_pre"]["health"].get("uptime_seconds")
    uptime_post = report["service_level_smoke_post"]["health"].get("uptime_seconds")
    report["post"] = {
        "library_revision_pre": rev_pre,
        "library_revision_post": rev_post,
        "uptime_pre": uptime_pre,
        "uptime_post": uptime_post,
        "smoke_namespace_info_status": ns_info_post["status"],
        "smoke_namespace_info_request_id": ns_info_post["request_id"],
    }
    report["library_revision_unchanged"] = rev_pre == rev_post
    report["uptime_continuity"] = (
        isinstance(uptime_pre, (int, float)) and isinstance(uptime_post, (int, float))
        and uptime_post > uptime_pre
    )
    report["smoke_namespace_absent_post"] = ns_info_post["status"] == 404

    print("===EVIDENCE-JSON===")
    print(json.dumps(report, indent=2, sort_keys=True))
    print("===END===")
    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except Exception as exc:
        print("===DRIVER-ERROR===")
        print(f"{type(exc).__name__}: {str(exc)[:200]}")
        raise SystemExit(1)

